const std = @import("std");
const CF = .{ .maxz = 65536, .dayz = 86400 };
pub const Conf = struct { prof_dirz_path: []const u8 = "~/.za-prof", stat_dirz_path: []const u8 = "~/.za-state", brow_exec_path: []const u8 = "", brow_head_mode: bool = false, pipe_mode_enab: bool = false, zalo_page_urlz: []const u8 = "https://chat.zalo.me/", type_dely_msec: [2]u32 = .{ 90, 260 }, acti_dely_secs: [2]u32 = .{ 6, 25 }, read_dely_msec: [2]u32 = .{ 800, 3500 }, capz_send_hour: u32 = 20, capz_send_dayz: u32 = 120, capz_newc_dayz: u32 = 5, capz_send_minu: u32 = 6, gapz_send_msec: u32 = 3000, quie_hour_rang: [2]u8 = .{ 23, 6 }, loca_utcz_mins: i32 = 420, warm_dayz_coun: u32 = 7, retr_coun_maxz: u32 = 3, read_msgz_maxz: u32 = 20, brow_time_secs: u32 = 60, logi_wait_secs: u32 = 300, smar_mode_enab: bool = false, smar_chai_orde: []const []const u8 = &.{ "clau", "llam" }, smar_clau_exec: []const u8 = "claude", smar_llam_exec: []const u8 = "llama-cli", smar_time_secs: u32 = 60, smar_clau_argz: []const []const u8 = &.{ "-p", "{p}" }, smar_llam_argz: []const []const u8 = &.{ "-p", "{p}", "-n", "200", "--no-display-prompt" }, reci_bulk_maxz: u32 = 5, rand_seed_fixd: u64 = 0, labl_sear_boxz: []const u8 = "Tìm kiếm", labl_mesg_boxz: []const u8 = "Nhập @, tin nhắn tới", labl_send_butt: []const u8 = "Gửi", labl_unre_mark: []const u8 = "unread", labl_qrcd_page: []const u8 = "Đăng nhập tài khoản Zalo", labl_pinz_butt: []const u8 = "Ghim hội thoại", labl_mute_butt: []const u8 = "Tắt thông báo", labl_forw_butt: []const u8 = "Chuyển tiếp", labl_grou_butt: []const u8 = "Tạo nhóm", labl_remi_butt: []const u8 = "Nhắc hẹn", labl_remi_titl: []const u8 = "Tiêu đề", labl_remi_time: []const u8 = "Thời gian", labl_remi_okay: []const u8 = "Tạo", labl_grou_name: []const u8 = "Tên nhóm", labl_chat_role: []const u8 = "listitem", labl_mesg_role: []const u8 = "article", labl_self_pref: []const u8 = "me: ", reci_pric_word: []const []const u8 = &.{ "price", "giá", "bao nhiêu" }, reci_pric_text: []const u8 = "", halt_word_list: []const []const u8 = &.{ "captcha", "xác minh", "bị khóa", "bị khoá", "tạm khóa", "tạm khoá", "hạn chế", "đăng nhập ở nơi khác", "logged in elsewhere", "locked", "suspended", "cảnh báo", "bất thường" } };
pub fn confLoad(allo: std.mem.Allocator, iozz: std.Io, path: []const u8) !Conf { const byte = std.Io.Dir.cwd().readFileAlloc(iozz, path, allo, .limited(CF.maxz)) catch |err| { if (err == error.FileNotFound) return .{}; return err; }; return confParse(allo, byte); }
pub fn confParse(allo: std.mem.Allocator, byte: []const u8) !Conf { const conf = std.json.parseFromSliceLeaky(Conf, allo, byte, .{ .ignore_unknown_fields = true, .allocate = .alloc_always }) catch return error.BadConfig; try confChek(conf); return conf; }
pub fn confChek(conf: Conf) !void { if (conf.type_dely_msec[0] == 0 or conf.type_dely_msec[0] > conf.type_dely_msec[1]) return error.BadConfig; if (conf.acti_dely_secs[0] == 0 or conf.acti_dely_secs[0] > conf.acti_dely_secs[1]) return error.BadConfig; if (conf.read_dely_msec[0] == 0 or conf.read_dely_msec[0] > conf.read_dely_msec[1]) return error.BadConfig; if (conf.capz_send_hour == 0 or conf.capz_send_dayz == 0 or conf.capz_send_dayz < conf.capz_send_hour or conf.capz_send_minu == 0) return error.BadConfig; if (conf.quie_hour_rang[0] > 23 or conf.quie_hour_rang[1] > 23) return error.BadConfig; if (conf.loca_utcz_mins < -720 or conf.loca_utcz_mins > 840) return error.BadConfig; if (conf.retr_coun_maxz == 0 or conf.retr_coun_maxz > 9 or conf.read_msgz_maxz == 0 or conf.brow_time_secs == 0) return error.BadConfig; if (conf.gapz_send_msec < 1000) return error.BadConfig; if (conf.smar_chai_orde.len == 0) return error.BadConfig; for (conf.smar_chai_orde) |item| if (!std.mem.eql(u8, item, "clau") and !std.mem.eql(u8, item, "llam")) return error.BadConfig; }
pub fn pathHome(allo: std.mem.Allocator, home: []const u8, path: []const u8) ![]u8 { if (std.mem.startsWith(u8, path, "~/") or std.mem.startsWith(u8, path, "~\\")) return std.fs.path.join(allo, &.{ home, path[2..] }); if (std.mem.eql(u8, path, "~")) return allo.dupe(u8, home); return allo.dupe(u8, path); }
